set_error_handler(function($n,$m,$f,$l){if(error_reporting()&$n)throw new ErrorException($m,0,$n,$f,$l);});
function same($a,$b){if($a!==$b)throw new RuntimeException('Expected '.var_export($a,true).'; got '.(is_string($b)&&strlen($b)>100?'string length '.strlen($b):var_export($b,true)));}
function check($x){if(!$x)throw new RuntimeException('Assertion failed');}
function raises($class,$fn){try{$fn();}catch(Throwable$e){if($e instanceof$class)return;throw$e;}throw new RuntimeException('Expected '.$class);}
function dbSetting($schema,$extra=[]){global$source;$s=(include$source.'config/config.php')['db'];$s['name']=$schema;return $extra+$s;}
function makeCache($kind,$path,$schema=''){return new myCache($kind,$kind==='File'?$path:dbSetting($schema),0);}
$job=getenv('CACHE_REVIEW_JOB');
if($job){$x=json_decode(base64_decode($job),true);$cache=makeCache($x['kind'],$x['path'],$x['schema']??'');
 if($x['type']==='hold'){$cache->synchronized('blocked',function()use($x){file_put_contents($x['ready'],'ready');for($i=0;$i<500&&!is_file($x['release']);$i++)usleep(10000);check(is_file($x['release']));});echo'ok';exit;}
 $result=$cache->rememberLocked('parallel',function()use($x){$h=fopen($x['counter'],'c+b');flock($h,LOCK_EX);$n=(int)stream_get_contents($h);rewind($h);ftruncate($h,0);fwrite($h,(string)($n+1));fflush($h);flock($h,LOCK_UN);fclose($h);usleep(80000);return 'computed';},60,5);same('computed',$result);echo'ok';exit;
}
class CacheClock extends myCache_File {public $clock=100;protected function now(){return$this->clock;}}
class CacheWake {public static $wakes=0;public $value='object';public function __wakeup(){self::$wakes++;}}
class LegacyCacheReview implements interface_cache {public $data=[];public function set($k,$v,$t){$this->data[$k]=$v;return true;}public function get($k){return$this->data[$k]??false;}public function remove($k){unset($this->data[$k]);return true;}public function clean(){return true;}}
class GcThrowsReview extends LegacyCacheReview {public function collectGarbage(){throw new RuntimeException('gc');}}
class GcNeedsArgsReview extends LegacyCacheReview {public $calls=0;public function collectGarbage($required){$this->calls++;}}
function callbackStream($h){return stream_get_contents($h);}
function cacheLegacyArg($arg){return is_resource($arg)?'resource':'scalar:'.(string)$arg;}
$passed=$failed=0;$scratch=sys_get_temp_dir().'/mystep-cache-'.bin2hex(random_bytes(6));mkdir($scratch,0700);
function test($name,$fn){global$passed,$failed;try{$fn();$passed++;echo'PASS '.$name.PHP_EOL;}catch(Throwable$e){$failed++;echo'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function directory($name){global$scratch;$p=$scratch.'/'.$name;if(!is_dir($p))mkdir($p,0700,true);return$p;}
function entryFile($path,$key){$h=md5($key);return$path.'/v2/'.substr($h,0,2).'/'.$h;}
function legacyEntry($path,$key,$value,$expire){$f=entryFile($path,$key);if(!is_dir(dirname($f)))mkdir(dirname($f),0700,true);file_put_contents($f,serialize(['version'=>2,'expire'=>$expire,'value'=>$value]));return$f;}
function rmTree($p){if(is_link($p)||is_file($p))unlink($p);elseif(is_dir($p)){foreach(new FilesystemIterator($p)as$f)rmTree($f->getPathname());rmdir($p);}}
function startJob($x){$env=getenv();$env['CACHE_REVIEW_JOB']=base64_encode(json_encode($x));$p=proc_open([PHP_BINARY,__FILE__],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);fclose($pipes[0]);return[$p,$pipes];}
function finishJob($job){list($p,$pipes)=$job;$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err!=='')throw new RuntimeException('Worker failed: '.$err);return$out;}
function parallelRemember($kind,$path,$schema=''){$counter=directory('counter-'.$kind).'/count';$jobs=[];for($i=0;$i<8;$i++)$jobs[]=startJob(['type'=>'remember','kind'=>$kind,'path'=>$path,'schema'=>$schema,'counter'=>$counter]);foreach($jobs as$j)same('ok',finishJob($j));same('1',file_get_contents($counter));}
function lockTimeout($kind,$path,$schema=''){$dir=directory('timeout-'.$kind);$ready=$dir.'/ready';$release=$dir.'/release';$job=startJob(['type'=>'hold','kind'=>$kind,'path'=>$path,'schema'=>$schema,'ready'=>$ready,'release'=>$release]);try{for($i=0;$i<300&&!is_file($ready);$i++)usleep(10000);check(is_file($ready));$c=makeCache($kind,$path,$schema);$called=0;raises(RuntimeException::class,function()use($c,&$called){$c->synchronized('blocked',function()use(&$called){$called++;},0);});same(0,$called);}finally{file_put_contents($release,'done');same('ok',finishJob($job));}}
